// CSD_RATIONALE_BEGIN
// mode_A (140/300 wrong, fast+low-token-budget) is the dominant failure class.
// Every prior attempt caps at ~53% accuracy. The structural root cause is that
// CloseSpanWithinBudget(400) tracks the longest SYNTACTICALLY complete SQL
// prefix, but that prefix is still SEMANTICALLY wrong when the model uses
// ungrounded identifiers (wrong table/column names, wrong casing, hallucinated
// aliases) or generates a plausible but logically incorrect query.
//
// Fix: Insert RegenerateUnitOnGroundingFailure as Phase 3 before CloseSpanWithinBudget.
// This helper generates SQL tokens via dead-end-avoiding steps and, at each
// completed schema-symbol boundary (table name, column name), checks whether
// the identifier token is grounded in the prompt context (i.e., appears in the
// provided schema). When an identifier is NOT grounded, it rolls back that unit
// and resamples with a persistent penalty on the rejected token. This directly
// addresses wrong-identifier failures while still producing parser.IsValidPrefix
// output.
//
// After Phase 3, CloseSpanWithinBudget(100) closes the span at the longest
// complete SQL prefix found in the grounding-corrected content.
//
// Budget: Phase1(≤5) + Phase2(1) + Phase3(500) + Phase4(100) = 606 ≤ 900.
// Expected avg token use: ~30 tokens (EOS terminates early for typical SQL).
//
// Guidance string: unchanged from attempt 72 (best proven; changes in 73-75
// all hurt accuracy).
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 preamble: Loop guard includes !insideConstrainedOut so the implication
//   is vacuous on every iteration. The only true-flip is via
//   RenderedEndsWith(generated, "<<"), at which point we set
//   currentConstrainedOut := [] and IsValidPrefix([]) holds by the method
//   precondition. EOS break leaves insideConstrainedOut = false, vacuous.
//
// Phase 2 OpenConstrainedSpan: Runs only when !insideConstrainedOut.
//   Postcondition sets currentConstrainedOut := []; IsValidPrefix([]) holds
//   by precondition. Sets insideConstrainedOut := true.
//
// Phase 3 RegenerateUnitOnGroundingFailure: Postcondition guarantees
//   parser.IsValidPrefix(resultConstrained). We set currentConstrainedOut :=
//   resultConstrained; the implication is satisfied. insideConstrainedOut
//   stays true (span left open by the helper).
//
// Phase 4 CloseSpanWithinBudget: Postcondition directly guarantees
//   (!insideConstrainedOut ==> currentConstrainedOut == []) and
//   (insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)).
//   Both branches are covered.
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//
// Phase 1: UnconstrainedStep costs 1 step and appends at most 1 token (0 on
//   EOS via break). Each iteration: steps += 1, |generated| grows by <= 1.
//   Preserved.
//
// Phase 2: OpenConstrainedSpan costs 1 step, appends exactly 1 "<<" token.
//   steps += 1, |generated| += 1. Preserved 1:1.
//
// Phase 3: RegenerateUnitOnGroundingFailure costs at most +phase3Budget
//   token-steps and |resultConstrained| <= phase3Budget by its cost contract
//   (rollback tokens and EOS still count against budget but are not visible
//   appends). We set generated := stablePrefix + resultConstrained and
//   steps := steps_before + phase3Budget. Then
//   |generated| = |stablePrefix| + |resultConstrained|
//             <= (|generatedPrefix| + steps_before) + phase3Budget
//             = |generatedPrefix| + steps_after. Preserved.
//
// Phase 4: CloseSpanWithinBudget postcondition: |cg| <= |generated| + closeBudget.
//   We set steps := steps_before + closeBudget. So
//   |cg| <= |generatedPrefix| + steps_before + closeBudget = |generatedPrefix|
//   + steps_after. Preserved. Dead-end and EOS tokens consumed internally count
//   against closeBudget even if not visibly appended.
//
// |currentConstrainedOut| <= |generated| after Phase 3:
//   |resultConstrained| <= |stablePrefix| + |resultConstrained| = |generated|
//   since |stablePrefix| >= 0. Trivially holds.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Output SQL: <<query>> where query is a valid SQL SELECT statement using ONLY the exact table and column names from the provided schema. The SQL must be placed between << and >>. No explanation, no markdown, no aliases not in the schema.");

var steps: nat := 0;

// Phase 1: Short preamble (at most 5 steps) to let model emit "SQL: <<"
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if model has not opened constrained span yet
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Schema-grounded SQL generation.
// RegenerateUnitOnGroundingFailure generates SQL token-by-token and checks each
// completed schema-symbol unit (table name, column name) for grounding in the
// prompt. Ungrounded identifiers are rolled back and resampled with penalties,
// directly addressing wrong table/column name failures.
if insideConstrainedOut && steps < maxSteps {
  var remaining3 := maxSteps - steps;
  var phase3Budget: nat := if remaining3 <= 500 then remaining3 else 500;
  var stablePrefix := generated[..|generated| - |currentConstrainedOut|];
  var constrainedPrompt := prompt + stablePrefix;
  var resultConstrained := helpers.RegenerateUnitOnGroundingFailure(
    lm, parser, constrainedPrompt, currentConstrainedOut, eosToken,
    phase3Budget, 3, 50
  );
  generated := stablePrefix + resultConstrained;
  currentConstrainedOut := resultConstrained;
  steps := steps + phase3Budget;
}

// Phase 4: Close the span at the longest complete SQL prefix.
// CloseSpanWithinBudget generates forward from the grounding-corrected content,
// tracking the longest prefix that parses as complete SQL and emitting ">>" there.
if insideConstrainedOut && steps < maxSteps {
  var remaining4 := maxSteps - steps;
  var closeBudget: nat := if remaining4 <= 100 then remaining4 else 100;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + closeBudget;
}

cost := steps;

